def has_dup(a):
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] == a[j]:
                return True
    return False

def has_dup(a):
    seen = set()
    for x in a:
        if x in seen:
            return True
        seen.add(x)
    return False
